"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["23617"],{96268(e){e.exports=JSON.parse('{"id":"V4-158","slug":"greenium","term":"Greenium","also_known_as":[],"difficulty":"Advanced","definition":"A greenium, short for green premium, is the lower yield, or higher price, that investors accept on green bonds compared with similar conventional bonds from the same issuer.","explanation":["If investors are willing to pay more for green bonds because of strong demand from sustainability-focused funds, the issuer can borrow slightly more cheaply through a green bond than through an ordinary bond with the same maturity and credit risk.","For example, if a government\u2019s ten-year conventional bond yields 3.50% and its ten-year green bond yields 3.47%, the greenium is about 0.03 percentage points, or 3 basis points.","Studies have generally found that greeniums exist but are small, often just a few basis points, and that they vary over time, by issuer and by market. In some cases, there is no measurable greenium.","The greenium is important because it affects whether issuing green bonds is financially attractive. Even a small greenium can encourage issuers to finance more green projects, although issuers also face extra costs for reporting and external reviews. For investors, a greenium means accepting a slightly lower return in exchange for funding environmental projects. Greeniums tend to be larger when demand for green bonds exceeds supply."],"note":"","total":1725,"prev":{"slug":"green-taxonomy","term":"Green Taxonomy"},"next":{"slug":"greenwashing","term":"Greenwashing"}}')}}]);